SELECT CASE WHEN txn_type IN ('REFUND', 'DEBIT') THEN 'tier_1' ELSE 'other' END AS txn_type_group, SUM(amount) AS total_amount, COUNT(*) AS cnt, SUM(SUM(amount)) OVER (ORDER BY CASE WHEN txn_type IN ('REFUND', 'DEBIT') THEN 'tier_1' ELSE 'other' END) AS cumulative_amount FROM transactions GROUP BY CASE WHEN txn_type IN ('REFUND', 'DEBIT') THEN 'tier_1' ELSE 'other' END ORDER BY txn_type_group ASC;
